INSERT INTO recipes (name, description, emoji, meal_type, prep_minutes, steps, tags) VALUES
('Ugali & Sukuma Wiki', 'The everyday Kenyan classic: firm ugali with garlicky sukuma wiki in tomato.', '🌽', 'LUNCH,DINNER', 30,
 E'1. Boil water and stir in maize flour until firm; cook 5 minutes more.\n2. Fry onions, add tomatoes and cook to a soft stew.\n3. Add chopped sukuma wiki and simmer 5-7 minutes.\n4. Serve hot with the greens.', 'budget,vegetarian,high-fibre'),
('Ugali na Maharagwe', 'Ugali with stewed beans and fresh cabbage. Filling and cheap.', '🫘', 'LUNCH,DINNER', 45,
 E'1. Soak and boil beans until soft.\n2. Fry onions and tomatoes, add beans and simmer.\n3. Steam shredded cabbage lightly.\n4. Serve with ugali.', 'budget,vegetarian,high-protein'),
('Githeri with Vegetables', 'Maize and beans slow-cooked with tomatoes, greens and a slice of avocado.', '🫘', 'LUNCH,DINNER', 40,
 E'1. Boil maize and beans until tender.\n2. Fry onions and tomatoes, add githeri.\n3. Stir in sukuma wiki and simmer 5 minutes.\n4. Serve with avocado.', 'budget,vegetarian,high-fibre'),
('Ndengu & Chapati', 'Creamy green grams curry with soft chapati and kachumbari.', '🫓', 'LUNCH,DINNER', 50,
 E'1. Boil ndengu until they split.\n2. Fry onions, garlic and tomatoes; add ndengu and simmer.\n3. Cook chapati on a hot pan.\n4. Serve with kachumbari.', 'vegetarian,high-protein'),
('Rice & Beans', 'Fluffy boiled rice with tomato-stewed beans and kachumbari.', '🍚', 'LUNCH,DINNER', 40,
 E'1. Boil rice until fluffy.\n2. Simmer cooked beans in a tomato-onion base.\n3. Mix kachumbari.\n4. Plate together.', 'budget,vegetarian'),
('Tilapia, Ugali & Kachumbari', 'Crispy fried tilapia, ugali, kachumbari and a little sukuma.', '🐟', 'LUNCH,DINNER', 35,
 E'1. Season tilapia with salt and lemon and fry until golden.\n2. Cook ugali.\n3. Toss tomato, onion and coriander for kachumbari.\n4. Serve with sukuma wiki.', 'high-protein,omega-3'),
('Omena, Ugali & Managu', 'Budget protein: sun-dried omena with ugali and managu greens.', '🐟', 'LUNCH,DINNER', 30,
 E'1. Wash omena and fry until crisp, then simmer in tomato sauce.\n2. Cook managu with onions.\n3. Serve with ugali.', 'budget,high-protein,iron-rich'),
('Matoke & Beef Stew', 'Mashed green bananas with a light beef stew.', '🍌', 'LUNCH,DINNER', 55,
 E'1. Peel and boil matoke until soft, then mash.\n2. Brown beef cubes with onions and simmer with tomato.\n3. Serve with kachumbari.', 'high-protein'),
('Chicken Stew & Rice', 'Chicken simmered in a tomato-onion sauce, with rice and spinach.', '🍗', 'DINNER,LUNCH', 50,
 E'1. Brown chicken pieces.\n2. Add onions, tomatoes and spices, simmer until tender.\n3. Boil rice and steam spinach.\n4. Serve together.', 'high-protein'),
('Pilau & Kachumbari', 'Spiced rice cooked with beef and pilau masala.', '🍛', 'LUNCH,DINNER', 60,
 E'1. Brown onions and beef with pilau masala.\n2. Add rice and stock, cook covered until done.\n3. Serve with kachumbari.', 'celebration'),
('Mukimo & Beef Stew', 'Mashed potatoes, maize and greens with a small portion of beef stew.', '🥔', 'LUNCH,DINNER', 60,
 E'1. Boil potatoes with maize and beans.\n2. Add steamed spinach and mash together.\n3. Serve with beef stew.', 'traditional'),
('Uji & Banana', 'Warm fermented porridge with a ripe banana.', '🥣', 'BREAKFAST', 15,
 E'1. Mix flour with water into a paste.\n2. Stir into boiling water and cook 10 minutes.\n3. Sweeten lightly and serve with banana.', 'budget,breakfast'),
('Tea & Mandazi', 'Milky tea with two fresh mandazi.', '☕', 'BREAKFAST', 25,
 E'1. Mix flour, sugar, cardamom and water into a dough; rest.\n2. Cut and deep fry until golden.\n3. Serve with hot milky tea.', 'breakfast'),
('Tea, Bread & Eggs', 'Quick protein-rich breakfast.', '🍳', 'BREAKFAST', 10,
 E'1. Boil eggs 8 minutes.\n2. Toast bread.\n3. Serve with a cup of milky tea.', 'quick,high-protein'),
('Sweet Potato & Tea', 'Boiled sweet potato with tea: slow-release energy.', '🍠', 'BREAKFAST,SNACK', 25,
 E'1. Wash and boil sweet potatoes until soft.\n2. Serve warm with tea.', 'budget,high-fibre'),
('Arrowroot & Avocado', 'Boiled arrowroots with creamy avocado and tea.', '🥑', 'BREAKFAST,SNACK', 30,
 E'1. Boil arrowroots 20 minutes.\n2. Slice avocado.\n3. Serve with tea.', 'vegetarian'),
('Chapati & Egg Scramble', 'Soft chapati with tomato-onion scrambled eggs.', '🍳', 'BREAKFAST,DINNER', 30,
 E'1. Cook chapati.\n2. Scramble eggs with onions and tomato.\n3. Serve together.', 'quick,high-protein'),
('Tropical Fruit Bowl', 'Banana, mango and pawpaw: vitamins on a budget.', '🥭', 'SNACK', 5,
 E'1. Slice the fruit and combine in a bowl.', 'snack,vegetarian,light'),
('Groundnuts & Orange', 'A handful of groundnuts with a juicy orange.', '🥜', 'SNACK', 2,
 E'1. Serve nuts alongside a peeled orange.', 'snack,vegetarian'),
('Mala & Banana', 'Fermented milk and a banana: a simple, filling snack.', '🥛', 'SNACK,BREAKFAST', 2,
 E'1. Pour cold mala and serve with a banana.', 'snack,quick'),
('Nyama Choma, Ugali & Kachumbari', 'Weekend favourite: grilled goat with ugali and fresh kachumbari.', '🍖', 'DINNER', 60,
 E'1. Grill seasoned goat meat over medium heat until cooked.\n2. Cook ugali.\n3. Serve with kachumbari.', 'celebration,high-protein');

